import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';
import { performance } from 'node:perf_hooks';

const candidate = process.argv[2];
const baseline = process.argv[3];
const repeats = Number(process.argv[4] ?? 5);
assert(candidate && baseline && repeats > 0);
const output = path.dirname(new URL(import.meta.url).pathname);
const work = fs.mkdtempSync(path.join(output, 'fixtures-'));
const env = { PATH: process.env.PATH, HOME: work, LANG: 'C.UTF-8', TZ: 'UTC', GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: '/dev/null', GIT_AUTHOR_NAME: 'Fixture', GIT_AUTHOR_EMAIL: 'fixture@example.invalid', GIT_COMMITTER_NAME: 'Fixture', GIT_COMMITTER_EMAIL: 'fixture@example.invalid' };
const git = (root, args) => execFileSync('git', args, {cwd: root, env, encoding:'utf8'}).trim();
const write = (root, files) => { for (const [file, body] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(root,file)), {recursive:true}); fs.writeFileSync(path.join(root,file),body); } };
const commit = (root, files, name) => { write(root, files); git(root,['add','.']); git(root,['commit','-qm',name]); return git(root,['rev-parse','HEAD']); };
const cases = [
 ['one-line-typescript', 'src/lib.ts', 'export const lib = () => 1;\n', 'export const lib = () => 2;\n'],
 ['local-bug', 'src/lib.ts', 'export const lib = (n = 1) => n > 0 ? n : 1;\n', 'export const lib = (n = 1) => n >= 0 ? n : 1;\n'],
 ['small-feature', 'src/lib.ts', 'export const lib = () => 1;\n', 'export const lib = (n = 1) => n + 1;\nexport const label = "ready";\n'],
 ['react-tsx', 'src/View.tsx', 'export const View = () => <button>Save</button>;\n', 'export const View = () => <button>Saved</button>;\n'],
 ['laravel-php', 'app/Services/Price.php', '<?php function price($n) { return $n; }\n', '<?php function price($n) { return max(0, $n); }\n'],
 ['python', 'src/price.py', 'def price(n):\n    return n\n', 'def price(n):\n    return max(0, n)\n'],
 ['shared-api', 'src/shared/api.ts', 'export interface Item { id: string }\n', 'export interface Item { id: string; name?: string }\n'],
 ['authentication', 'src/auth/authorize.ts', 'export const allowed = (role: string) => role !== "guest";\n', 'export const allowed = (role: string) => role === "admin";\n'],
 ['database-migration', 'db/migrations/001.sql', 'CREATE TABLE users (id INTEGER);\n', 'CREATE TABLE users (id INTEGER PRIMARY KEY);\n'],
 ['unresolved-dynamic-import', 'src/lib.ts', 'export const lib = () => 1;\n', 'export const lib = (name: string) => import(name);\n'],
];
const fixtures = cases.map(([name,file,before,after]) => {
 const root = path.join(work,name); fs.mkdirSync(root); git(root,['init','-q']);
 const initial = {
  'package.json': JSON.stringify({name:'fixture',private:true,type:'module'}),
  'src/lib.ts': 'export const lib = () => 1;\n',
  'src/app.ts':'import { lib } from "./lib.js";\nexport const app = () => lib();\n',
  'src/unrelated.ts':'export const unrelated = 0;\n',
  'test/steps/app.steps.ts':'import { Given } from "@cucumber/cucumber";\nimport { app } from "../../src/app.js";\nGiven("app starts", () => { app(); });\n',
  'test/features/app.feature':'Feature: app\n  Scenario: SCN-FX-001 start\n    Given app starts\n',
  [file]:before,
 };
 if(name === 'shared-api') initial['src/shared/consumer.ts'] = 'import type { Item } from "./api.js";\nexport const id = (item: Item) => item.id;\n';
 const alternateBase = commit(root,initial,'initial');
 const base = commit(root,{'src/unrelated.ts':'export const unrelated = 1;\n'},'unrelated change');
 const head = commit(root,{[file]:after},'candidate change');
 return {name,root,base,alternateBase,head};
});
const child = path.join(output,'measure.mjs');
fs.writeFileSync(child, `import { performance } from 'node:perf_hooks';
const { computeImpactSet } = await import(process.argv[2]);
const f = JSON.parse(process.argv[3]);
const samples = [];
for (const [label, baseSha] of [['first',f.base],['repeat',f.base],['differentBase',f.alternateBase]]) {
 const start = performance.now();
 const result = computeImpactSet({root:f.root,baseSha,headSha:f.head});
 samples.push({label,ms:performance.now()-start,result});
}
process.stdout.write(JSON.stringify(samples));\n`);
const stats = values => { const a=[...values].sort((a,b)=>a-b), n=a.length;return {median:n%2?a[Math.floor(n/2)]:(a[n/2-1]+a[n/2])/2,p95:a[Math.ceil(n*0.95)-1],max:a[n-1],min:a[0]}; };
const start = new Date().toISOString();
const raw = [];
for (const f of fixtures) {
 for(let repeat=0;repeat<repeats;repeat++) {
  const round={case:f.name,repeat};
  for (const label of repeat%2 ? ['candidate','baseline'] : ['baseline','candidate']) {
   const source = label==='candidate'?candidate:baseline;
   const begin=performance.now();
   const run=spawnSync(process.execPath,['--import',pathToFileURL(path.join(candidate,'node_modules/tsx/dist/loader.mjs')).href,child,pathToFileURL(path.join(source,'src/adapters/impact-set.ts')).href,JSON.stringify(f)],{env,cwd:source,encoding:'utf8',maxBuffer:20*1024*1024});
   assert.equal(run.status,0,run.stderr);
   round[label]={processMs:performance.now()-begin,samples:JSON.parse(run.stdout)};
  }
  for(let index=0;index<3;index++) {
   if (f.name === 'unresolved-dynamic-import') {
    assert.equal(round.baseline.samples[index].result.mode, index < 2 ? 'targeted' : 'full');
    assert.equal(round.candidate.samples[index].result.mode, 'full');
   } else assert.deepEqual(round.candidate.samples[index].result,round.baseline.samples[index].result, `${f.name} result mismatch`);
  }
  assert.deepEqual(round.candidate.samples[0].result,round.candidate.samples[1].result);
  raw.push(round);
  fs.writeFileSync(path.join(output,"checkpoint.json"),JSON.stringify(raw,null,2));
 }
 console.error(`completed ${f.name}`);
}
const summary=fixtures.map(f=>{
 const rows=raw.filter(row=>row.case===f.name);
 const summarize=side=>Object.fromEntries(['first','repeat','differentBase','analysisSequence','process'].map((label,index)=>[label,stats(rows.map(row=>label==='process'?row[side].processMs:label==='analysisSequence'?row[side].samples.reduce((a,s)=>a+s.ms,0):row[side].samples[index].ms))]));
 return {case:f.name,identities:{base:f.base,alternateBase:f.alternateBase,head:f.head},equivalent:f.name !== 'unresolved-dynamic-import',expectedSafetyChange:f.name === 'unresolved-dynamic-import' ? 'baseline targeted -> candidate full' : null,mode:rows[0].candidate.samples[0].result.mode,securitySensitive:rows[0].candidate.samples[0].result.securitySensitive,baseline:summarize('baseline'),candidate:summarize('candidate')};
});
const report={kind:'impact-analysis-microbenchmark/v1',issue:1576,startedAt:start,endedAt:new Date().toISOString(),node:process.version,cpu:os.cpus()[0]?.model,repeats,baseline,candidate,fixtureDirectory:work,limitations:['This measures computeImpactSet first/repeat/different-base calls only, not an Issue end-to-end workflow, LLM work, review quality, test execution, CI or delivery.','No provider token usage or cost was collected; no token saving is claimed.','Fresh process per side and repetition; first call includes compiler initialization. Process timing includes loader and process startup. OS caches are not flushed.','Five repetitions are a small sample; p95 is nearest-rank and equals max for n=5.','Run order alternates; shared host load can affect measurements.'],summary,raw};
fs.writeFileSync(path.join(output,'results.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(summary,null,2));

