 process.env.ASC_EXECUTION_CONTEXT_MODE=mode;reads=[];processes=[];stdout='';active=true;const start=performance.now();let status;
 try{status=await main(['workflow','advance',`--staging=${staging}`]);}finally{active=false;}
 const result=JSON.parse(stdout),dispatch=result.agentDispatch,embedded=dispatch?JSON.parse(dispatch.prompt).handoff:null;
 const counts={};for(const r of reads){const v=counts[r.path]??={count:0,bytes:0};v.count++;v.bytes+=r.bytes;}
 observations.push({mode,iteration,status,ms:performance.now()-start,outputBytes:Buffer.byteLength(stdout),topLevel:Object.keys(result),handoffBytes:result.handoff?Buffer.byteLength(JSON.stringify(result.handoff)):0,dispatchPromptBytes:dispatch?Buffer.byteLength(dispatch.prompt):0,dispatchDuplicatesTopLevelHandoff:embedded?JSON.stringify(embedded)===JSON.stringify(result.handoff):null,workUnitId:result.handoff?.workUnit?.workUnitId??null,targetStep:result.targetStep,readCalls:reads.length,readBytes:reads.reduce((a,r)=>a+r.bytes,0),reads:counts,processCalls:processes.length,processes});
}
} finally { active=false; fs.readFileSync=originalRead;cp.spawnSync=originalSpawn;cp.execFileSync=originalExec;process.stdout.write=originalOut;syncBuiltinESMExports(); }
fs.writeFileSync('/tmp/asc-1576-workflow-probe-result.json',JSON.stringify({root,staging,importMs,observations},null,2)+'\n');

